BEGIN;

-- Opakovatelný preview seed. Neobsahuje klienty, zájmy, holds, smlouvy ani ceny jednotek.
SELECT set_config('app.commercial_status_command', 'on', true);

VALUES ('d0000000-0000-4000-8000-000000000001', 'Develo Group', 'develo-group', 'active')
ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, slug=EXCLUDED.slug, status=EXCLUDED.status;

ON CONFLICT (id) DO UPDATE SET email=EXCLUDED.email, display_name=EXCLUDED.display_name;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO UPDATE SET status='active', accepted_at=COALESCE(tenant_memberships.accepted_at,EXCLUDED.accepted_at);

ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, status='active';
SELECT 'd0000000-0000-4000-8000-000000000001', role.id, permission.id
FROM roles role CROSS JOIN permissions permission
WHERE role.id='d4000000-0000-4000-8000-000000000001' ON CONFLICT DO NOTHING;
SELECT 'd0000000-0000-4000-8000-000000000001', role.id, permission.id
FROM roles role JOIN permissions permission ON permission.code IN
  ('tenant.read','membership.read','role.read','project.read','project.manage','structure.manage','construction_status.manage','unit.read','unit.manage','commercial_status.manage','accessory.read','accessory.manage')
WHERE role.id='d4000000-0000-4000-8000-000000000002' ON CONFLICT DO NOTHING;
SELECT 'd0000000-0000-4000-8000-000000000001', role.id, permission.id
FROM roles role JOIN permissions permission ON permission.code IN ('tenant.read','membership.read','role.read','project.read','unit.read','accessory.read')
WHERE role.id IN ('d4000000-0000-4000-8000-000000000003','d4000000-0000-4000-8000-000000000004') ON CONFLICT DO NOTHING;
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, location=EXCLUDED.location, manager_membership_id=EXCLUDED.manager_membership_id,
  planned_handover_from=EXCLUDED.planned_handover_from, planned_handover_to=EXCLUDED.planned_handover_to;

ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, sort_order=EXCLUDED.sort_order;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO UPDATE SET structure_id=EXCLUDED.structure_id, layout=EXCLUDED.layout, floor_label=EXCLUDED.floor_label,
  floor_number=EXCLUDED.floor_number, area_m2=EXCLUDED.area_m2, orientation=EXCLUDED.orientation, commercial_status=EXCLUDED.commercial_status;

SELECT ('f1000000-0000-4000-8000-' || lpad(row_number() OVER (ORDER BY unit.code)::text,12,'0'))::uuid,
  unit.tenant_id,unit.project_id,unit.id,NULL,unit.commercial_status,'seed','Výchozí stav preview seedu','d3000000-0000-4000-8000-000000000001','2026-07-01'
FROM units unit WHERE unit.tenant_id='d0000000-0000-4000-8000-000000000001'
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name,category=EXCLUDED.category,allows_sharing=EXCLUDED.allows_sharing;

ON CONFLICT (id) DO UPDATE SET area_m2=EXCLUDED.area_m2,operational_status='active',archived_at=NULL;

ON CONFLICT (id) DO NOTHING;

SELECT ('a3000000-0000-4000-8000-' || lpad(row_number() OVER (ORDER BY mapping.accessory_id)::text,12,'0'))::uuid,
  'd0000000-0000-4000-8000-000000000001', mapping.project_id, mapping.unit_id, mapping.accessory_id, '2026-01-01',
  'd3000000-0000-4000-8000-000000000001'
FROM (VALUES
  ('e0000000-0000-4000-8000-000000000001'::uuid,'f0000000-0000-4000-8000-000000000001'::uuid,'a1000000-0000-4000-8000-000000000001'::uuid),
  ('e0000000-0000-4000-8000-000000000001'::uuid,'f0000000-0000-4000-8000-000000000001'::uuid,'a1000000-0000-4000-8000-000000000002'::uuid),
  ('e0000000-0000-4000-8000-000000000001'::uuid,'f0000000-0000-4000-8000-000000000001'::uuid,'a1000000-0000-4000-8000-000000000003'::uuid),
  ('e0000000-0000-4000-8000-000000000001'::uuid,'f0000000-0000-4000-8000-000000000002'::uuid,'a1000000-0000-4000-8000-000000000004'::uuid),
  ('e0000000-0000-4000-8000-000000000001'::uuid,'f0000000-0000-4000-8000-000000000003'::uuid,'a1000000-0000-4000-8000-000000000005'::uuid),
  ('e0000000-0000-4000-8000-000000000001'::uuid,'f0000000-0000-4000-8000-000000000003'::uuid,'a1000000-0000-4000-8000-000000000006'::uuid),
  ('e0000000-0000-4000-8000-000000000001'::uuid,'f0000000-0000-4000-8000-000000000004'::uuid,'a1000000-0000-4000-8000-000000000007'::uuid),
  ('e0000000-0000-4000-8000-000000000001'::uuid,'f0000000-0000-4000-8000-000000000004'::uuid,'a1000000-0000-4000-8000-000000000008'::uuid),
  ('e0000000-0000-4000-8000-000000000001'::uuid,'f0000000-0000-4000-8000-000000000005'::uuid,'a1000000-0000-4000-8000-000000000009'::uuid),
  ('e0000000-0000-4000-8000-000000000001'::uuid,'f0000000-0000-4000-8000-000000000006'::uuid,'a1000000-0000-4000-8000-000000000010'::uuid),
  ('e0000000-0000-4000-8000-000000000001'::uuid,'f0000000-0000-4000-8000-000000000006'::uuid,'a1000000-0000-4000-8000-000000000011'::uuid),
  ('e0000000-0000-4000-8000-000000000002'::uuid,'f0000000-0000-4000-8000-000000000007'::uuid,'a1000000-0000-4000-8000-000000000012'::uuid),
  ('e0000000-0000-4000-8000-000000000002'::uuid,'f0000000-0000-4000-8000-000000000007'::uuid,'a1000000-0000-4000-8000-000000000013'::uuid),
  ('e0000000-0000-4000-8000-000000000002'::uuid,'f0000000-0000-4000-8000-000000000008'::uuid,'a1000000-0000-4000-8000-000000000014'::uuid),
  ('e0000000-0000-4000-8000-000000000002'::uuid,'f0000000-0000-4000-8000-000000000008'::uuid,'a1000000-0000-4000-8000-000000000015'::uuid),
  ('e0000000-0000-4000-8000-000000000002'::uuid,'f0000000-0000-4000-8000-000000000009'::uuid,'a1000000-0000-4000-8000-000000000016'::uuid),
  ('e0000000-0000-4000-8000-000000000002'::uuid,'f0000000-0000-4000-8000-000000000009'::uuid,'a1000000-0000-4000-8000-000000000017'::uuid),
  ('e0000000-0000-4000-8000-000000000002'::uuid,'f0000000-0000-4000-8000-000000000009'::uuid,'a1000000-0000-4000-8000-000000000018'::uuid),
  ('e0000000-0000-4000-8000-000000000003'::uuid,'f0000000-0000-4000-8000-000000000010'::uuid,'a1000000-0000-4000-8000-000000000019'::uuid),
  ('e0000000-0000-4000-8000-000000000003'::uuid,'f0000000-0000-4000-8000-000000000010'::uuid,'a1000000-0000-4000-8000-000000000020'::uuid)
) mapping(project_id,unit_id,accessory_id)
ON CONFLICT (id) DO NOTHING;

SELECT ('a4000000-0000-4000-8000-' || lpad(row_number() OVER (ORDER BY accessory.id)::text,12,'0'))::uuid,
  accessory.tenant_id,accessory.project_id,accessory.id,
  CASE type.category WHEN 'parking' THEN 450000 WHEN 'wallbox' THEN 85000 WHEN 'garage' THEN 790000
    WHEN 'cellar' THEN COALESCE(accessory.area_m2,4)*65000 ELSE 120000 END,
  'CZK','2026-01-01','Výchozí ceník preview seedu','d3000000-0000-4000-8000-000000000001'
FROM accessories accessory JOIN accessory_types type
  ON type.tenant_id=accessory.tenant_id AND type.id=accessory.accessory_type_id
WHERE accessory.tenant_id='d0000000-0000-4000-8000-000000000001'
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

COMMIT;
